package com.lexorion.payroll.api;import com.lexorion.payroll.domain.*;import jakarta.validation.constraints.*;import java.time.*;import java.util.UUID;public final class PayrollDtos{private PayrollDtos(){}public record CreatePayrollEmployee(@NotBlank@Pattern(regexp="^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$")String employeeCode,@NotNull PayrollStatus status,@NotBlank@Pattern(regexp="^[A-Z]{3}$")String currency,@NotNull PayFrequency payFrequency,@NotNull LocalDate effectiveFrom,@Null UUID organizationId,@Null UUID workspaceId,@Null UUID userId,@Null UUID employeeId,@Null UUID payrollEmployeeId,@Null UUID platformUserId,@Null String role){}public record UpdatePayrollEmployee(PayrollStatus status,@Pattern(regexp="^[A-Z]{3}$")String currency,PayFrequency payFrequency,LocalDate effectiveFrom,@Size(max=63)String payGroup,@Size(max=6)String workState,@Size(max=120)String workLocation,@Null UUID organizationId,@Null UUID workspaceId,@Null UUID userId,@Null UUID employeeId,@Null UUID payrollEmployeeId,@Null UUID platformUserId,@Null String role){}public record PayrollEmployeeResponse(String employeeCode,PayrollStatus status,String currency,PayFrequency payFrequency,LocalDate effectiveFrom,String payGroup,String workState,String workLocation){public static PayrollEmployeeResponse from(PayrollEmployee e){return new PayrollEmployeeResponse(e.getEmployeeCode(),e.getStatus(),e.getCurrency(),e.getPayFrequency(),e.getEffectiveFrom(),e.getPayGroup(),e.getWorkState(),e.getWorkLocation());}}}
